// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // Record the current sequenceNumber before any call
        uint64 seqBefore = c.sequenceNumber();

        // We need to call from the depositor account to satisfy the require
        // First set the depositorAccount to the caller
        // Since depositorAccount is public, we can read it
        address depositor = c.depositorAccount();

        // Call from the depositor account
        vm.prank(depositor);
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);

        uint64 seqAfter = c.sequenceNumber();

        // The general rule: after a successful call, the sequenceNumber must either stay the same
        // (if the call reverted in some other way, but we assume it didn't) OR be set to _sequenceNumber.
        // Since the reference C does NOT modify sequenceNumber, it must remain unchanged.
        // The mutant sets it to 0, breaking this rule.
        assertTrue(seqAfter == seqBefore || seqAfter == _sequenceNumber);
    }
}

